// Cloudflare entry point: the Next.js app built by OpenNext, plus the cron trigger from wrangler.jsonc.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import app from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };

export default {
  fetch: app.fetch,

  /** Runs the daily job by calling /api/cron inside the worker, with the same secret an outside caller would need. */
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) {
      console.error("Daily job skipped: set the CRON_SECRET secret on this worker.");
      return;
    }
    const request = new Request("https://tester.internal/api/cron", { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    const response: Response = await app.fetch(request, env, ctx);
    console.log(`Daily job: ${response.status} ${await response.text()}`);
  },
};
